package com.bank.security.model;

import java.time.LocalDate;

// A signed, time-boxed exception. Auditable: who approved, why, until when.
public class RiskAcceptance {
    private final String approvedBy;      // a security owner, NOT the developer
    private final String justification;   // business + compensating control
    private final LocalDate expiryDate;   // gate re-blocks after this date

    public RiskAcceptance(String approvedBy, String justification, LocalDate expiryDate) {
        this.approvedBy = approvedBy;
        this.justification = justification;
        this.expiryDate = expiryDate;
    }

    // Valid only if not expired as of today.
    public boolean isValidOn(LocalDate today) {
        return !today.isAfter(expiryDate);
    }

    public String getApprovedBy() { return approvedBy; }
    public String getJustification() { return justification; }
    public LocalDate getExpiryDate() { return expiryDate; }
}
