package com.bank.security.model;

// One scanner finding with the three signals that drive the decision.
public class Finding {
    private final String id;              // e.g. CVE-2024-1234
    private final String component;       // the vulnerable dependency
    private final Severity severity;      // from CVSS
    private final boolean reachable;      // is the vulnerable code actually called
    private final boolean onKevList;      // CISA Known Exploited Vulnerabilities
    private final boolean newlyIntroduced;// first seen in this build
    private final RiskAcceptance exception; // null if no signed exception

    public Finding(String id, String component, Severity severity, boolean reachable,
                   boolean onKevList, boolean newlyIntroduced, RiskAcceptance exception) {
        this.id = id;
        this.component = component;
        this.severity = severity;
        this.reachable = reachable;
        this.onKevList = onKevList;
        this.newlyIntroduced = newlyIntroduced;
        this.exception = exception;
    }

    public String getId() { return id; }
    public String getComponent() { return component; }
    public Severity getSeverity() { return severity; }
    public boolean isReachable() { return reachable; }
    public boolean isOnKevList() { return onKevList; }
    public boolean isNewlyIntroduced() { return newlyIntroduced; }
    public RiskAcceptance getException() { return exception; }
}
