package com.bank.security.policy;

import com.bank.security.model.Finding;
import com.bank.security.model.Severity;
import java.time.LocalDate;
import java.util.Map;
import java.util.logging.Logger;

// Decides whether a single finding should block the build, and its SLA in hours.
public class SecurityGatePolicy {
    private static final Logger log = Logger.getLogger(SecurityGatePolicy.class.getName());

    // SLA hours by severity — matches security-gate.yml.
    private final Map<Severity, Integer> slaHours = Map.of(
            Severity.CRITICAL, 72,
            Severity.HIGH, 720,
            Severity.MEDIUM, 2160,
            Severity.LOW, 4320
    );

    // Returns true if this finding must FAIL the build.
    public boolean shouldBlock(Finding f, LocalDate today) {
        // A valid signed exception suppresses the block until it expires.
        if (f.getException() != null && f.getException().isValidOn(today)) {
            log.info(() -> "EXCEPTION honored for " + f.getId()
                    + " approvedBy=" + f.getException().getApprovedBy()
                    + " until=" + f.getException().getExpiryDate());
            return false;
        }

        // Rule 1: anything actively exploited (KEV) blocks, regardless of CVSS.
        if (f.isOnKevList()) {
            log.severe(() -> "BLOCK " + f.getId() + " — on CISA KEV (actively exploited)");
            return true;
        }
        // Rule 2: a reachable CRITICAL blocks.
        if (f.getSeverity() == Severity.CRITICAL && f.isReachable()) {
            log.severe(() -> "BLOCK " + f.getId() + " — reachable CRITICAL in " + f.getComponent());
            return true;
        }
        // Rule 3: a newly introduced HIGH blocks (stop new risk entering).
        if (f.getSeverity() == Severity.HIGH && f.isNewlyIntroduced()) {
            log.warning(() -> "BLOCK " + f.getId() + " — newly introduced HIGH");
            return true;
        }
        // Otherwise: do not block, just track against an SLA.
        log.info(() -> "TRACK " + f.getId() + " — SLA " + slaFor(f.getSeverity()) + "h (no block)");
        return false;
    }

    public int slaFor(Severity severity) {
        return slaHours.get(severity);
    }
}
