package com.bank.security.gate;

import com.bank.security.model.Finding;
import com.bank.security.policy.SecurityGatePolicy;
import java.time.LocalDate;
import java.util.List;
import java.util.logging.Logger;

// Runs the policy over all findings and produces the final build verdict.
public class BuildGateEvaluator {
    private static final Logger log = Logger.getLogger(BuildGateEvaluator.class.getName());
    private final SecurityGatePolicy policy;

    public BuildGateEvaluator(SecurityGatePolicy policy) {
        this.policy = policy;
    }

    // true = build passes, false = build fails.
    public boolean evaluate(List<Finding> findings, LocalDate today) {
        int blockers = 0;
        for (Finding f : findings) {
            if (policy.shouldBlock(f, today)) {
                blockers++;
            }
        }
        if (blockers > 0) {
            log.severe(() -> "BUILD FAILED — " + blockers + " blocking finding(s)");
            return false;
        }
        log.info("BUILD PASSED — no blocking findings");
        return true;
    }
}
