package com.bank.security;

import com.bank.security.gate.BuildGateEvaluator;
import com.bank.security.model.Finding;
import com.bank.security.model.RiskAcceptance;
import com.bank.security.model.Severity;
import com.bank.security.policy.SecurityGatePolicy;
import java.time.LocalDate;
import java.util.List;
import java.util.logging.Logger;

// Runnable demo: four findings matching the four banking problems.
public class SecurityGateApplication {
    private static final Logger log = Logger.getLogger(SecurityGateApplication.class.getName());

    public static void main(String[] args) {
        LocalDate today = LocalDate.of(2026, 10, 25);

        // Problem 1: reachable CRITICAL in the JSON parser used by payments → BLOCK.
        Finding f1 = new Finding("CVE-2024-1111", "fast-json", Severity.CRITICAL,
                true, false, true, null);

        // Problem 2: HIGH in logging lib but NOT reachable → TRACK, do not block.
        Finding f2 = new Finding("CVE-2024-2222", "slow-logger", Severity.HIGH,
                false, false, false, null);

        // Problem 3: CRITICAL with no patch but a signed, unexpired exception → honored.
        RiskAcceptance accepted = new RiskAcceptance("priya.security-lead",
                "No patch yet; input sanitized upstream; revisit at upgrade", LocalDate.of(2026, 12, 31));
        Finding f3 = new Finding("CVE-2024-3333", "legacy-xml", Severity.CRITICAL,
                true, false, false, accepted);

        // Problem 4: Medium CVSS but on CISA KEV (actively exploited) → BLOCK.
        Finding f4 = new Finding("CVE-2024-4444", "img-codec", Severity.MEDIUM,
                false, true, false, null);

        SecurityGatePolicy policy = new SecurityGatePolicy();
        BuildGateEvaluator gate = new BuildGateEvaluator(policy);

        log.info("=== National Bank of India — payments pipeline security gate ===");
        boolean passed = gate.evaluate(List.of(f1, f2, f3, f4), today);
        log.info(() -> "FINAL VERDICT: " + (passed ? "PASS" : "FAIL"));
    }
}
